}

input {
  font-family: inherit;
  font-size: inherit;
  border: none;
  outline: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
