  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: none;
  cursor: pointer;
  position: relative;
  transition: color var(--transition);
}

.toggle-tab::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
  transform-origin: center;
}

.toggle-tab:hover { color: var(--text); }

.toggle-tab--active {
  color: var(--red);
}

.toggle-tab--active::after { transform: scaleX(1); }

.toggle-content {
  display: none;
  animation: fadeIn 0.4s ease;
}

.toggle-content--active { display: block; }

.toggle-content h3 {
  font-size: 1.8rem;
  margin-bottom: 1rem;
}

.toggle-content p {
  color: var(--text-dim);
  font-size: 1.1rem;
  line-height: 1.8;
  max-width: 700px;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Instructor Grid --- */
.filter-bar {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 3rem;
  justify-content: center;
}

.filter-btn {
  padding: 0.7rem 1.5rem;
  background: var(--bg-card);
  color: var(--text-dim);
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.filter-btn:hover {
  color: var(--text);
  border-color: var(--text-dim);
}

.filter-btn--active {
  background: var(--red);
  color: var(--text);
  border-color: var(--red);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  opacity: 1;
  transform: scale(1);
}

.instructor-card[style*="display: none"] {
  display: none !important;
}

.instructor-card--hidden {
  display: none;
}

.instructor-card__photo {
  aspect-ratio: 3 / 4;
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.instructor-card__photo-placeholder {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: rgba(255,0,0,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-family: var(--font-heading);
  color: var(--red);
}

.instructor-card__info {
  padding: 1.5rem;
}

.instructor-card__name {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 0.25rem;
}

.instructor-card__location {
  font-size: 0.9rem;
  color: var(--red);
  margin-bottom: 1.25rem;
}

.instructor-card__link {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text);
  padding: 0.6rem 1.5rem;
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.instructor-card__link:hover {
  background: var(--red);
  border-color: var(--red);
  color: var(--text);
}

/* --- FAQ Accordion --- */
.accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion__item {
  border-bottom: 1px solid var(--border);
}

.accordion__trigger {
  width: 100%;
  padding: 1.5rem 0;
  background: none;
  color: var(--text);
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  transition: color var(--transition);
}

.accordion__trigger:hover { color: var(--red); }

.accordion__icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  position: relative;
  transition: transform var(--transition);
}

.accordion__icon::before,
.accordion__icon::after {
  content: '';
  position: absolute;
  background: currentColor;
  transition: transform var(--transition);
}

.accordion__icon::before {
  top: 11px;
  left: 0;
  width: 24px;
  height: 2px;
}

.accordion__icon::after {
  top: 0;
  left: 11px;
  width: 2px;
  height: 24px;
}

.accordion__item--active .accordion__icon::after {
  transform: rotate(90deg);
}

.accordion__item--active .accordion__trigger {
  color: var(--red);
}

.accordion__panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion__panel-inner {
  padding: 0 0 1.5rem;
  color: var(--text-dim);
  line-height: 1.7;
  font-size: 1rem;
}

/* --- Digital Features --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 1.5rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 2.5rem;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.feature-card__icon {
  font-size: 2rem;
  margin-bottom: 1.25rem;
  width: 56px;
  height: 56px;
  background: rgba(255,0,0,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.feature-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.feature-card p {
  color: var(--text-dim);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* --- Method Section --- */
.method-section {
  background: #0d0d0d;
}

.method-body {
  max-width: 750px;
  margin: 0 auto;
  color: var(--text-dim);
  font-size: 1.15rem;
  line-height: 1.8;
  text-align: center;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .nav__links { display: none; }

  .nav__mobile-toggle { display: flex; }

  .nav__utility .btn--outline { display: none; }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
  }

  .two-ways {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  :root { --nav-height: 64px; }

  .container { padding: 0 1.25rem; }

  .section { padding: 4rem 0; }

  .hero { min-height: 70vh; }

  .nav__utility .btn { display: none; }

  .footer__grid {
    grid-template-columns: 1fr;
  }

  .newsletter__inner {
    flex-direction: column;
    text-align: center;
  }

  .newsletter__form {
    min-width: 0;
    width: 100%;
    flex-direction: column;
  }

  .schedule-table thead { display: none; }

  .schedule-table tbody td {
    display: block;
    padding: 1rem 1.25rem;
  }

  .schedule-table tbody td::before {
    content: attr(data-label);
    display: block;
    font-family: var(--font-heading);
    font-size: 0.75rem;
    text-transform: uppercase;
    color: var(--red);
    margin-bottom: 0.25rem;
  }

  .schedule-table tbody tr {
    display: block;
    margin-bottom: 1rem;
    border: 1px solid var(--border);
    background: var(--bg-card);
  }

  .toggle-tab { max-width: none; }

  .btn-group { justify-content: center; }

  .filter-bar { justify-content: flex-start; }

  .carousel__slide { aspect-ratio: 16 / 10; }
}

/* --- Mobile Nav Overlay --- */
.nav__mobile-overlay {
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(10, 10, 10, 0.98);
  backdrop-filter: blur(20px);
  display: flex;
  flex-direction: column;
  padding: 2rem;
  gap: 0;
  transform: translateX(100%);
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 999;
  overflow-y: auto;
}

.nav__mobile-overlay--open {
  transform: translateX(0);
}

.nav__mobile-link {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-dim);
  padding: 1rem 0;
  border-bottom: 1px solid var(--border);
  display: block;
}

.nav__mobile-link:hover { color: var(--red); }

/* --- Scroll animations --- */
.fade-up {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-up--visible {
  opacity: 1;
  transform: translateY(0);
}
