8	  // --- Mobile Navigation ---
9	  function initMobileNav() {
10	    var toggle = document.querySelector('.nav__mobile-toggle');
11	    var overlay = document.querySelector('.nav__mobile-overlay');
12	    if (!toggle || !overlay) return;
13	
14	    toggle.addEventListener('click', function () {
15	      var isOpen = overlay.classList.toggle('nav__mobile-overlay--open');
16	      toggle.setAttribute('aria-expanded', isOpen);
17	    });
18	
19	    overlay.querySelectorAll('.nav__mobile-link').forEach(function (link) {
