21	        overlay.classList.remove('nav__mobile-overlay--open');
22	        toggle.setAttribute('aria-expanded', 'false');
23	      });
24	    });
25	  }
26	
27	  // --- Carousel ---
28	  function initCarousel() {
29	    var carousel = document.querySelector('.carousel');
30	    if (!carousel) return;
31	
32	    var track = carousel.querySelector('.carousel__track');
33	    var slides = carousel.querySelectorAll('.carousel__slide');
34	    var prevBtn = carousel.querySelector('.carousel__prev');
35	    var nextBtn = carousel.querySelector('.carousel__next');
36	    var dotsContainer = carousel.querySelector('.carousel__dots');
37	    var currentIndex = 0;
38	    var totalSlides = slides.length;
39	    var autoplayInterval;
40	    var isTransitioning = false;
41	
42	    if (totalSlides < 2 && prevBtn && nextBtn) {
43	      prevBtn.style.display = 'none';
44	      nextBtn.style.display = 'none';
45	      return;
46	    }
47	
48	    // Create dots
49	    for (var i = 0; i < totalSlides; i++) {
50	      var dot = document.createElement('button');
51	      dot.className = 'carousel__dot' + (i === 0 ? ' carousel__dot--active' : '');
52	      dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
53	      dot.addEventListener('click', (function (idx) {
54	        return function () { goToSlide(idx); };
55	      })(i));
56	      dotsContainer.appendChild(dot);
57	    }
58	
59	    var dots = dotsContainer.querySelectorAll('.carousel__dot');
60	
61	    function goToSlide(index) {
62	      if (isTransitioning || index === currentIndex) return;
63	      isTransitioning = true;
64	
65	      currentIndex = index;
66	      track.style.transform = 'translateX(-' + (index * 100) + '%)';
67	
68	      dots.forEach(function (d, i) {
69	        d.classList.toggle('carousel__dot--active', i === index);
70	      });
71	
72	      setTimeout(function () {
73	        isTransitioning = false;
74	      }, 500);
75	    }
76	
77	    function nextSlide() { goToSlide((currentIndex + 1) % totalSlides); }
78	    function prevSlide() { goToSlide((currentIndex - 1 + totalSlides) % totalSlides); }
79	
80	    if (prevBtn) prevBtn.addEventListener('click', prevSlide);
81	    if (nextBtn) nextBtn.addEventListener('click', nextSlide);
82	
83	    // Touch support
84	    var touchStartX = 0;
85	    var touchEndX = 0;
86	
87	    carousel.addEventListener('touchstart', function (e) {
88	      touchStartX = e.changedTouches[0].screenX;
89	    }, { passive: true });
90	
91	    carousel.addEventListener('touchend', function (e) {
92	      touchEndX = e.changedTouches[0].screenX;
93	      var diff = touchStartX - touchEndX;
94	      if (Math.abs(diff) > 50) {
95	        if (diff > 0) nextSlide();
96	        else prevSlide();
97	      }
98	    });
99	
100	    // Autoplay
101	    function startAutoplay() {
102	      autoplayInterval = setInterval(nextSlide, 5000);
103	    }
104	
105	    function stopAutoplay() {
106	      clearInterval(autoplayInterval);
107	    }
108	
109	    startAutoplay();
110	
111	    carousel.addEventListener('mouseenter', stopAutoplay);
112	    carousel.addEventListener('mouseleave', startAutoplay);
113	    carousel.addEventListener('touchstart', stopAutoplay);
114	    carousel.addEventListener('touchend', function () {
115	      setTimeout(startAutoplay, 3000);
116	    });
117	  }
