119	  // --- Floor/Treadmill Toggle ---
120	  function initToggleTabs() {
121	    var tabs = document.querySelectorAll('.toggle-tab');
122	    var contents = document.querySelectorAll('.toggle-content');
123	    if (!tabs.length) return;
124	
125	    tabs.forEach(function (tab) {
126	      tab.addEventListener('click', function () {
127	        var target = tab.getAttribute('data-target');
128	
129	        tabs.forEach(function (t) { t.classList.remove('toggle-tab--active'); });
130	        tab.classList.add('toggle-tab--active');
131	
132	        contents.forEach(function (c) {
