143	
144	    var buttons = filterBar.querySelectorAll('.filter-btn');
145	    var cards = document.querySelectorAll('.instructor-card');
146	
147	    buttons.forEach(function (btn) {
148	      btn.addEventListener('click', function () {
149	        var location = btn.getAttribute('data-filter');
150	
151	        buttons.forEach(function (b) { b.classList.remove('filter-btn--active'); });
152	        btn.classList.add('filter-btn--active');
153	
154	        cards.forEach(function (card) {
155	          if (location === 'all' || card.getAttribute('data-location') === location) {
156	            card.style.display = '';
157	            card.style.opacity = '1';
158	            card.style.transform = 'scale(1)';
159	          } else {
160	            card.style.display = 'none';
161	          }
162	        });
163	      });
