169	    var accordion = document.querySelector('.accordion');
170	    if (!accordion) return;
171	
172	    var items = accordion.querySelectorAll('.accordion__item');
173	
174	    items.forEach(function (item) {
175	      var trigger = item.querySelector('.accordion__trigger');
176	      var panel = item.querySelector('.accordion__panel');
177	
178	      trigger.addEventListener('click', function () {
179	        var isActive = item.classList.contains('accordion__item--active');
180	
181	        // Close all
182	        items.forEach(function (other) {
183	          other.classList.remove('accordion__item--active');
184	          var otherPanel = other.querySelector('.accordion__panel');
185	          otherPanel.style.maxHeight = '0';
186	        });
187	
188	        // Open clicked (if it wasn't already open)
189	        if (!isActive) {
190	          item.classList.add('accordion__item--active');
191	          panel.style.maxHeight = panel.scrollHeight + 'px';
192	        }
193	      });
194	    });
195	  }
