198	  function initNewsletter() {
199	    var forms = document.querySelectorAll('.newsletter__form');
200	    if (!forms.length) return;
201	
202	    forms.forEach(function (form) {
203	      var input = form.querySelector('.newsletter__input');
204	      var feedback = form.querySelector('.newsletter__feedback');
205	
206	      form.addEventListener('submit', function (e) {
207	        e.preventDefault();
208	
209	        var email = input.value.trim();
210	
211	        if (!email) {
212	          input.classList.add('newsletter__input--error');
213	          feedback.textContent = 'Please enter your email address.';
214	          feedback.className = 'newsletter__feedback newsletter__feedback--error';
215	          return;
216	        }
217	
218	        // RFC 5322 simplified email regex
219	        var emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*\.[a-zA-Z]{2,}$/;
220	
221	        if (!emailRegex.test(email)) {
222	          input.classList.add('newsletter__input--error');
223	          feedback.textContent = 'Please enter a valid email address.';
224	          feedback.className = 'newsletter__feedback newsletter__feedback--error';
225	          return;
226	        }
227	
228	        // Success
229	        input.classList.remove('newsletter__input--error');
230	        input.value = '';
231	        feedback.textContent = 'You\'re in! Check your inbox for a confirmation.';
232	        feedback.className = 'newsletter__feedback newsletter__feedback--success';
233	      });
234	
235	      input.addEventListener('input', function () {
236	        input.classList.remove('newsletter__input--error');
237	        feedback.textContent = '';
238	      });
239	    });
240	  }
